package com.ghostai.v8;
import android.app.*;import android.os.*;import android.content.*;import android.Manifest;import android.content.pm.PackageManager;import android.net.*;import android.speech.*;import android.webkit.*;import java.util.*;import java.security.*;import javax.crypto.SecretKeyFactory;import javax.crypto.spec.PBEKeySpec;import android.util.Base64;
import rikka.shizuku.Shizuku;
public class MainActivity extends Activity{
 static final int MIC=9, SHIZUKU_REQ=42; WebView web; SpeechRecognizer sr; static final String CODM="com.activision.callofduty.shooter";
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xff050914);getWindow().setNavigationBarColor(0xff050914);web=new WebView(this);web.setBackgroundColor(0xff050914);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.addJavascriptInterface(new Bridge(),"Ghost");setContentView(web);web.loadUrl("file:///android_asset/index.html");Shizuku.addRequestPermissionResultListener((requestCode,grantResult)->{if(requestCode==SHIZUKU_REQ)web.evaluateJavascript("shizukuStatus("+org.json.JSONObject.quote(grantResult==PackageManager.PERMISSION_GRANTED?"Shizuku permission granted":"Shizuku permission denied")+")",null);});}
 class Bridge{
 @JavascriptInterface public String registerAccount(String username,String password){try{android.content.SharedPreferences sp=getSharedPreferences("ghost_local_auth",MODE_PRIVATE);if(sp.contains("username"))return "{\"ok\":false,\"message\":\"A local account already exists on this device. Sign in with it.\"}";byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);String hash=hashPassword(password,salt);sp.edit().putString("username",username).putString("salt",Base64.encodeToString(salt,Base64.NO_WRAP)).putString("hash",hash).apply();return "{\"ok\":true,\"message\":\"Local account created. Sign in with your username and password.\"}";}catch(Exception e){return "{\"ok\":false,\"message\":\"Account creation failed.\"}";}}
 @JavascriptInterface public String verifyLogin(String username,String password){try{android.content.SharedPreferences sp=getSharedPreferences("ghost_local_auth",MODE_PRIVATE);String saved=sp.getString("username",null),saltText=sp.getString("salt",null),savedHash=sp.getString("hash",null);if(saved==null||saltText==null||savedHash==null)return "{\"ok\":false,\"message\":\"No local account exists. Tap CREATE LOCAL ACCOUNT first.\"}";if(!saved.equals(username))return "{\"ok\":false,\"message\":\"Incorrect username or password.\"}";byte[] salt=Base64.decode(saltText,Base64.NO_WRAP);String candidate=hashPassword(password,salt);boolean ok=MessageDigest.isEqual(candidate.getBytes(java.nio.charset.StandardCharsets.UTF_8),savedHash.getBytes(java.nio.charset.StandardCharsets.UTF_8));return ok?"{\"ok\":true,\"message\":\"Welcome back.\"}":"{\"ok\":false,\"message\":\"Incorrect username or password.\"}";}catch(Exception e){return "{\"ok\":false,\"message\":\"Login verification failed.\"}";}}
 private String hashPassword(String password,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(password.toCharArray(),salt,150000,256);try{byte[] out=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();return Base64.encodeToString(out,Base64.NO_WRAP);}finally{spec.clearPassword();}}
 @JavascriptInterface public void launchGame(){runOnUiThread(()->{Intent i=getPackageManager().getLaunchIntentForPackage(CODM);if(i==null)web.evaluateJavascript("toast('COD Mobile Global is not installed.')",null);else startActivity(i);});}
 @JavascriptInterface public String device(){Intent b=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=b==null?-1:b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),t=b==null?-1:b.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,-1);ActivityManager.MemoryInfo m=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(m);return "{\"battery\":"+level+",\"temp\":"+(t<0?-1:t/10.0)+",\"ram\":"+(m.availMem/1048576)+",\"cores\":"+Runtime.getRuntime().availableProcessors()+"}";}
 @JavascriptInterface public String network(){ConnectivityManager c=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);Network n=c.getActiveNetwork();NetworkCapabilities x=n==null?null:c.getNetworkCapabilities(n);boolean ok=x!=null&&x.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);String k=x==null?"Offline":x.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":x.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"Mobile data":"Connected";return "{\"connected\":"+ok+",\"type\":\""+k+"\"}";}
 @JavascriptInterface public String shizukuStatus(){try{if(!Shizuku.pingBinder())return "{\"available\":false,\"granted\":false,\"message\":\"Start Shizuku first\"}";boolean g=Shizuku.checkSelfPermission()==PackageManager.PERMISSION_GRANTED;return "{\"available\":true,\"granted\":"+g+",\"message\":"+org.json.JSONObject.quote(g?"Connected • permission granted":"Connected • permission needed")+"}";}catch(Exception e){return "{\"available\":false,\"granted\":false,\"message\":\"Shizuku not available\"}";}}
 @JavascriptInterface public void requestShizuku(){runOnUiThread(()->{try{if(!Shizuku.pingBinder()){web.evaluateJavascript("shizukuStatus('Start Shizuku service first')",null);return;}if(Shizuku.checkSelfPermission()!=PackageManager.PERMISSION_GRANTED)Shizuku.requestPermission(SHIZUKU_REQ);else web.evaluateJavascript("shizukuStatus('Shizuku permission already granted')",null);}catch(Exception e){web.evaluateJavascript("shizukuStatus('Shizuku unavailable')",null);}});}
 @JavascriptInterface public void voice(){runOnUiThread(()->{if(!SpeechRecognizer.isRecognitionAvailable(MainActivity.this)){web.evaluateJavascript("toast('Speech recognition unavailable.')",null);return;}if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}listen();});}
 }
 void listen(){if(sr!=null)sr.destroy();sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){web.evaluateJavascript("voiceStatus('Listening…')",null);}public void onBeginningOfSpeech(){}public void onRmsChanged(float f){}public void onBufferReceived(byte[]b){}public void onEndOfSpeech(){}public void onError(int e){web.evaluateJavascript("voiceStatus('Could not hear that. Try again.')",null);}public void onResults(Bundle b){ArrayList<String>a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);String s=a==null||a.isEmpty()?"":a.get(0);web.evaluateJavascript("voiceCommand("+org.json.JSONObject.quote(s)+")",null);}public void onPartialResults(Bundle b){}public void onEvent(int e,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"en-IN");sr.startListening(i);}
 public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==MIC&&g.length>0&&g[0]==0)listen();}
 protected void onDestroy(){if(sr!=null)sr.destroy();if(web!=null)web.destroy();super.onDestroy();}
}
